def compressir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    result = []
    i = 0
    n = len(texto)
    while i < n:
        ch = texto[i]
        count = 1
        i += 1
        while i < n and texto[i] == ch:
            count += 1
            i += 1
        result.append(ch + str(count))
    return "".join(result)

def aplanar(datos: list) -> list:
    def flatten(seq):
        result = []
        for item in seq:
            if isinstance(item, (list, tuple)):
                result.extend(flatten(item))
            else:
                result.append(item)
        return result
    return flatten(datos)

import csv
import io

def parsear_ventas(texto: str) -> list[dict]:
    if not texto or not texto.strip():
        return []
    reader = csv.reader(io.StringIO(texto))
    rows = list(reader)
    expected_header = ['fecha', 'producto', 'cantidad', 'precio']
    if rows[0] != expected_header:
        raise ValueError("Header line mismatch")
    result = []
    for row in rows[1:]:
        if len(row) == 0:
            continue
        if len(row) != 4:
            raise ValueError(f"Row has {len(row)} fields: {row}")
        fecha, producto, cantidad_str, precio_str = row
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError(f"Cantidad '{cantidad_str}' is not an integer")
        if cantidad < 0:
            raise ValueError(f"Cantidad '{cantidad_str}' is negative")
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError(f"Precio '{precio_str}' is not a number")
        result.append({
            'fecha': fecha,
            'producto': producto,
            'cantidad': cantidad,
            'precio': precio
        })
    return result

import datetime

def parsear_fecha(texto: str) -> str:
    texto = texto.strip()
    if '-' in texto:
        parts = texto.split('-')
        if len(parts) != 3:
            raise ValueError("Formato inválido")
        try:
            year = int(parts[0])
            month = int(parts[1])
            day = int(parts[2])
        except ValueError:
            raise ValueError("Fecha inválida")
        try:
            datetime.date(year, month, day)
        except ValueError:
            raise ValueError("Fecha inválida")
        return f"{year:04d}-{month:02d}-{day:02d}"
    elif '/' in texto:
        parts = texto.split('/')
        if len(parts) != 3:
            raise ValueError("Formato inválido")
        try:
            day = int(parts[0])
            month = int(parts[1])
            year = int(parts[2])
        except ValueError:
            raise ValueError("Fecha inválida")
        try:
            datetime.date(year, month, day)
        except ValueError:
            raise ValueError("Fecha inválida")
        return f"{year:04d}-{month:02d}-{day:02d}"
    elif " de " in texto:
        tokens = texto.split()
        if len(tokens) != 5:
            raise ValueError("Formato inválido")
        day_str = tokens[0]
        month_name = tokens[2]
        year_str = tokens[4]
        try:
            day = int(day_str)
            year = int(year_str)
        except ValueError:
            raise ValueError("Fecha inválida")
        month_map = {
            "enero": 1,
            "febrero": 2,
            "marzo": 3,
            "abril": 4,
            "mayo": 5,
            "junio": 6,
            "julio": 7,
            "agosto": 8,
            "septiembre": 9,
            "octubre": 10,
            "noviembre": 11,
            "diciembre": 12
        }
        if month_name.lower() not in month_map:
            raise ValueError(f"Mes no válido: {month_name}")
        month = month_map[month_name.lower()]
        try:
            datetime.date(year, month, day)
        except ValueError:
            raise ValueError("Fecha inválida")
        return f"{year:04d}-{month:02d}-{day:02d}"
    else:
        raise ValueError("Formato no reconocido")

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

def mochila(pesos: list[int], valores: list[int], capacidad: int) -> tuple[int, list[int]]:
    if len(pesos) != len(valores):
        raise ValueError("Lengths of pesos and valores must match")
    if any(p < 0 for p in pesos):
        raise ValueError("Weights must be non-negative")
    if capacidad < 0:
        raise ValueError("Capacity must be non-negative")

    n = len(pesos)
    if n == 0:
        return (0, [])

    best_val = -1
    best_weight = float('inf')
    best_indices = []

    for mask in range(1 << n):
        total_weight = 0
        total_value = 0
        indices = []
        for i in range(n):
            if mask & (1 << i):
                total_weight += pesos[i]
                total_value += valores[i]
                indices.append(i)
        if total_weight <= capacidad:
            if total_value > best_val:
                best_val = total_value
                best_weight = total_weight
                best_indices = indices
            elif total_value == best_val:
                if total_weight < best_weight:
                    best_val = total_value
                    best_weight = total_weight
                    best_indices = indices
                elif total_weight == best_weight:
                    if len(indices) < len(best_indices):
                        best_val = total_value
                        best_weight = total_weight
                        best_indices = indices
                    elif len(indices) == len(best_indices):
                        if indices < best_indices:
                            best_val = total_value
                            best_weight = total_weight
                            best_indices = indices
    return (best_val, best_indices)

from collections import OrderedDict

class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave in self._datos:
            self._datos.move_to_end(clave)
            return self._datos[clave]
        return None

    def put(self, clave, valor):
        if self.capacidad == 0:
            return
        if clave in self._datos:
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
        else:
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
